code = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    # Find the full horizontal or vertical 2-line.
    horizontal = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    vertical = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    # The background is the most common non-line color.
    counts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    bg = max(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (2, bg)]
    if horizontal is not None:
        lo, hi = min(r for r, c in pts), max(r for r, c in pts)
        if lo > horizontal:
            dr = horizontal + 1 - lo
            far = hi + dr + 1
        else:
            dr = horizontal - 1 - hi
            far = lo + dr - 1
        for r, c in pts:
            g[r][c] = bg
        for r, c in pts:
            g[r + dr][c] = grid[r][c]
        if 0 <= far < h:
            g[far] = [8] * w
    elif vertical is not None:
        lo, hi = min(c for r, c in pts), max(c for r, c in pts)
        if lo > vertical:
            dc = vertical + 1 - lo
            far = hi + dc + 1
        else:
            dc = vertical - 1 - hi
            far = lo + dc - 1
        for r, c in pts:
            g[r][c] = bg
        for r, c in pts:
            g[r][c + dc] = grid[r][c]
        if 0 <= far < w:
            for r in range(h):
                g[r][far] = 8
    return g
'''
pfile = programs/'task-e385f17c.py'
pfile.write_text(code)
print(pfile)
